#!/usr/bin/env python3
"""
Benchmark script for Poisson Image Editing solvers
Uses the 10 test images from fpie benchmark suite (square6-10, circle6-10)
Outputs results in COLUMN-FORMAT: each row = one test configuration
FIXED: Properly parses hybrid CPU perf output (P-cores + E-cores)
"""

import subprocess
import csv
import re
import os
import sys
from pathlib import Path

# ============================================================
# CONFIGURATION
# ============================================================

# Test images from the fpie benchmark suite (generated by tests/data.py)
TEST_IMAGES = [
    ("square6.png", "square6", 4356),
    ("circle6.png", "circle6", 4291),
    ("square7.png", "square7", 16900),
    ("circle7.png", "circle7", 16727),
    ("square8.png", "square8", 66564),
    ("circle8.png", "circle8", 66043),
    ("square9.png", "square9", 264196),
    ("circle9.png", "circle9", 262341),
    ("square10.png", "square10", 1052676),
    ("circle10.png", "circle10", 1049489),
]

# Output directories
OUTPUT_DIR = "results"
OUTPUT_CSV = os.path.join(OUTPUT_DIR, "benchmark_results_msrb.csv")

# Fixed parameters
N_ITER = 5000
BACKEND = "openmp"

# Check if perf is available
PERF_AVAILABLE = False
try:
    subprocess.run(["perf", "--version"], capture_output=True, check=True)
    PERF_AVAILABLE = True
    print("✓ perf detected - cache metrics will be collected")
except:
    print("⚠ perf not available - cache metrics will be marked as '-'")

# ============================================================
# EXPERIMENT CONFIGURATIONS
# ============================================================

# CPU cores to test
CPU_CORES = [1, 2, 4, 8]

# Tile sizes for BrbSolver and MsrbSolver
TILE_SIZES = [16, 32, 64, 128, 256]

# Grid sizes for GridSolver
GRID_SIZES = [(16, 16), (32, 32), (64, 64), (128, 128), (256, 256)]

# MSRB parameters
A_MAX_VALUES = [1, 4, 8]
CONV_THRESHOLD_VALUES = [1e-1, 1e-2]

# ============================================================
# HELPER FUNCTIONS
# ============================================================

def setup_output_dir():
    """Create results directory if it doesn't exist"""
    Path(OUTPUT_DIR).mkdir(exist_ok=True)

def run_with_perf(cmd):
    """Run command with perf for hybrid CPUs (combines P-core + E-core)"""
    if PERF_AVAILABLE:
        # Use generic events that automatically combine P and E cores
        perf_cmd = [
            "perf", "stat", 
            "-e", "cycles,instructions,cache-references,cache-misses,branches,branch-misses",
            "-o", os.path.join(OUTPUT_DIR, "perf_output.txt")
        ]
        full_cmd = perf_cmd + cmd
        result = subprocess.run(full_cmd, capture_output=True, text=True)
    else:
        result = subprocess.run(cmd, capture_output=True, text=True)
    return result

def parse_fpie_output(output):
    """Extract metrics from fpie output"""
    metrics = {
        "n_vars": None,
        "iterations": None,
        "error": None,
        "time": None,
        "converged_early": False
    }
    
    vars_match = re.search(r"# of vars:\s*(\d+)", output)
    if vars_match:
        metrics["n_vars"] = int(vars_match.group(1))
    
    conv_match = re.search(r"Converged (?:early )?at iteration\s+(\d+)", output)
    if conv_match:
        metrics["converged_early"] = True
        metrics["iterations"] = int(conv_match.group(1))
    
    iter_match = re.findall(r"Iter\s+(\d+),\s+abs error\s+\[([\d\.\s\-e]+)\]", output)
    if iter_match:
        last_iter = iter_match[-1]
        if not metrics["iterations"]:
            metrics["iterations"] = int(last_iter[0])
        error_str = last_iter[1]
        errors = [float(x) for x in error_str.split()]
        metrics["error"] = max(errors)
    
    time_match = re.search(r"Time elapsed:\s+([\d\.]+)s", output)
    if time_match:
        metrics["time"] = float(time_match.group(1))
    
    return metrics

def parse_perf_output():
    """Extract cache metrics from perf output (handles both regular and hybrid CPU output)"""
    if not PERF_AVAILABLE:
        return "-", "-"
    
    try:
        perf_file = os.path.join(OUTPUT_DIR, "perf_output.txt")
        with open(perf_file, "r") as f:
            content = f.read()
        
        total_cache_misses = 0
        total_cache_refs = 0
        
        # Case 1: Regular perf output (single value)
        misses_match = re.search(r'([\d,]+)\s+cache-misses', content)
        refs_match = re.search(r'([\d,]+)\s+cache-references', content)
        
        if misses_match and refs_match:
            # Regular format
            total_cache_misses = int(misses_match.group(1).replace(",", ""))
            total_cache_refs = int(refs_match.group(1).replace(",", ""))
        else:
            # Case 2: Hybrid CPU output (P-core + E-core separate)
            # Sum cpu_core and cpu_atom values
            for line in content.split('\n'):
                # Cache misses
                if 'cache-misses' in line:
                    match = re.search(r'([\d,]+)\s+cpu_(?:core|atom)/cache-misses/', line)
                    if match:
                        total_cache_misses += int(match.group(1).replace(",", ""))
                
                # Cache references
                if 'cache-references' in line:
                    match = re.search(r'([\d,]+)\s+cpu_(?:core|atom)/cache-references/', line)
                    if match:
                        total_cache_refs += int(match.group(1).replace(",", ""))
        
        return total_cache_misses, total_cache_refs
    except Exception as e:
        print(f"  Warning: Could not parse perf output: {e}")
        return "-", "-"

def calculate_tpo(time, iterations, n_vars):
    """Time per operation (TpO) in nanoseconds"""
    if time != "-" and iterations and n_vars and time > 0 and iterations > 0 and n_vars > 0:
        total_ops = iterations * n_vars
        return (time * 1e9) / total_ops
    return "-"

def calculate_cmpo(cache_misses, iterations, n_vars):
    """Cache miss per operation (CMpO)"""
    if cache_misses != "-" and iterations and n_vars and iterations > 0 and n_vars > 0:
        try:
            misses = int(cache_misses) if isinstance(cache_misses, str) else cache_misses
            total_ops = iterations * n_vars
            return misses / total_ops
        except (ValueError, TypeError):
            return "-"
    return "-"

def build_command(source, target, mask, output, n_iter, backend, method, params):
    """Build fpie command with given parameters"""
    cmd = ["fpie", "-s", source, "-t", target, "-m", mask, "-o", output, 
           "-n", str(n_iter), "-b", backend, "--method", method]
    
    for key, value in params.items():
        if key == "c":
            cmd.extend(["-c", str(value)])
        elif key == "tile":
            cmd.extend(["--tile", str(value)])
        elif key == "grid_x":
            cmd.extend(["--grid-x", str(value)])
        elif key == "grid_y":
            cmd.extend(["--grid-y", str(value)])
        elif key == "a_max":
            cmd.extend(["--a-max", str(value)])
        elif key == "conv_threshold":
            cmd.extend(["--conv-threshold", str(value)])
    
    return cmd

def run_single_test(solver_name, method, params, img_file, img_name, pixels):
    """Run a single test and return all metrics as a dict with configuration info"""
    
    # Build output filename
    output_filename = f"{img_name}_{solver_name}"
    for key, val in params.items():
        if key == "conv_threshold":
            output_filename += f"_{key}{val:.0e}".replace('.', '_')
        else:
            output_filename += f"_{key}{val}"
    output_filename += ".png"
    output_path = os.path.join(OUTPUT_DIR, output_filename)
    
    cmd = build_command(img_file, img_file, img_file, output_path,
                        N_ITER, BACKEND, method, params)
    
    result = run_with_perf(cmd)
    metrics = parse_fpie_output(result.stdout + result.stderr)
    cache_misses, cache_refs = parse_perf_output()
    
    actual_iterations = metrics["iterations"] if metrics["iterations"] else N_ITER
    
    tpo = calculate_tpo(metrics["time"], actual_iterations, metrics["n_vars"])
    cmpo = calculate_cmpo(cache_misses, actual_iterations, metrics["n_vars"])
    
    # Build result row as a dictionary
    result_row = {
        "solver": solver_name,
        "method": method,
        "image": img_name,
        "pixels": pixels,
        "cores": params.get("c", "-"),
        "tile_size": params.get("tile", "-"),
        "grid_x": params.get("grid_x", "-"),
        "grid_y": params.get("grid_y", "-"),
        "a_max": params.get("a_max", "-"),
        "conv_threshold": params.get("conv_threshold", "-"),
        "time_seconds": metrics["time"] if metrics["time"] else "-",
        "actual_iterations": actual_iterations,
        "n_vars": metrics["n_vars"] if metrics["n_vars"] else "-",
        "residual_error": metrics["error"] if metrics["error"] else "-",
        "converged_early": "Yes" if metrics["converged_early"] else "No",
        "tpo_ns": tpo,
        "cmpo": cmpo,
        "cache_misses": cache_misses,
        "cache_references": cache_refs,
    }
    
    return result_row

# ============================================================
# MAIN BENCHMARK LOOP
# ============================================================

def main():
    # Create results directory
    setup_output_dir()
    
    # Check if we're in the tests directory with image files
    if not os.path.exists("square6.png"):
        print("Error: Test images not found!")
        print("Please run 'python3 data.py' first to generate the test images.")
        print("Then run this script from the tests/ directory.")
        sys.exit(1)
    
    # Prepare CSV file
    csv_file = open(OUTPUT_CSV, "w", newline="")
    
    # Define CSV columns
    columns = [
        "solver", "method", "image", "pixels", "cores", 
        "tile_size", "grid_x", "grid_y", "a_max", "conv_threshold",
        "time_seconds", "actual_iterations", "n_vars", "residual_error", 
        "converged_early", "tpo_ns", "cmpo", "cache_misses", "cache_references"
    ]
    
    writer = csv.DictWriter(csv_file, fieldnames=columns)
    writer.writeheader()
    
    print(f"\n{'='*80}")
    print(f"Starting Benchmark Suite (Column Format)")
    print(f"Test images: {len(TEST_IMAGES)} images (square6-10, circle6-10)")
    print(f"Fixed max iterations: {N_ITER}")
    print(f"Backend: {BACKEND}")
    print(f"Output directory: {OUTPUT_DIR}/")
    print(f"Results CSV: {OUTPUT_CSV}")
    print(f"{'='*80}\n")
    
    total_runs = 0

        # ====================================================
    # EQU SOLVER (baseline)
    # ====================================================
    for c in CPU_CORES:
        print(f"\n--- EquSolver: cores={c} ---")
        params = {"c": c}
        
        for img_file, img_name, pixels in TEST_IMAGES:
            print(f"  Running on {img_name}...", end=" ", flush=True)
            result = run_single_test("EquSolver", "equ", params, img_file, img_name, pixels)
            writer.writerow(result)
            print(f"done ({result['time_seconds']}s)")
            total_runs += 1
        print(f"  Completed {len(TEST_IMAGES)} runs for EquSolver cores={c}")
    
    # ====================================================
    # GRID SOLVER
    # ====================================================
    for c in CPU_CORES:
        for gx, gy in GRID_SIZES:
            print(f"\n--- GridSolver: cores={c}, grid=({gx},{gy}) ---")
            params = {"c": c, "grid_x": gx, "grid_y": gy}
            
            for img_file, img_name, pixels in TEST_IMAGES:
                print(f"  Running on {img_name}...", end=" ", flush=True)
                result = run_single_test("GridSolver", "grid", params, img_file, img_name, pixels)
                writer.writerow(result)
                print(f"done ({result['time_seconds']}s)")
                total_runs += 1
            print(f"  Completed {len(TEST_IMAGES)} runs for GridSolver cores={c} grid=({gx},{gy})")
    
    # ====================================================
    # BRB SOLVER (Block Red-Black)
    # ====================================================
    for c in CPU_CORES:
        for tile in TILE_SIZES:
            print(f"\n--- BrbSolver: cores={c}, tile={tile} ---")
            params = {"c": c, "tile": tile}
            
            for img_file, img_name, pixels in TEST_IMAGES:
                print(f"  Running on {img_name}...", end=" ", flush=True)
                result = run_single_test("BrbSolver", "brb", params, img_file, img_name, pixels)
                writer.writerow(result)
                print(f"done ({result['time_seconds']}s)")
                total_runs += 1
            print(f"  Completed {len(TEST_IMAGES)} runs for BrbSolver cores={c} tile={tile}")
    
    
    # ====================================================
    # MSRB SOLVER (Multi-Sweep Red-Black)
    # ====================================================
    print(f"\n{'='*80}")
    print(f"MSRB SOLVER (Multi-Sweep Red-Black with Early Stopping)")
    print(f"{'='*80}")
    
    for c in CPU_CORES:
        for tile in TILE_SIZES:
            for a_max in A_MAX_VALUES:
                for conv_threshold in CONV_THRESHOLD_VALUES:
                    print(f"\n--- MsrbSolver: cores={c}, tile={tile}, a_max={a_max}, conv={conv_threshold:.0e} ---")
                    params = {
                        "c": c, 
                        "tile": tile, 
                        "a_max": a_max, 
                        "conv_threshold": conv_threshold
                    }
                    
                    for img_file, img_name, pixels in TEST_IMAGES:
                        print(f"  Running on {img_name}...", end=" ", flush=True)
                        result = run_single_test("MsrbSolver", "msrb", params, img_file, img_name, pixels)
                        
                        # Format time display
                        time_str = f"{result['time_seconds']:.4f}s" if result['time_seconds'] != "-" else "ERROR"
                        print(f"done ({time_str}, iters={result['actual_iterations']})")
                        
                        # Show cache metrics if available
                        if result['cache_misses'] != "-":
                            print(f"    Cache Misses: {int(result['cache_misses']):,}, Cache Refs: {int(result['cache_references']):,}")
                        
                        writer.writerow(result)
                        total_runs += 1
                        csv_file.flush()  # Save after each run
                    print(f"  Completed {len(TEST_IMAGES)} runs for MsrbSolver cores={c} tile={tile} a_max={a_max} conv={conv_threshold:.0e}")
    
    csv_file.close()
    
    print(f"\n{'='*80}")
    print(f"Benchmark complete!")
    print(f"Results CSV: {OUTPUT_CSV}")
    print(f"Output images: {OUTPUT_DIR}/")
    print(f"\nTotal runs completed: {total_runs}")
    print(f"{'='*80}")

if __name__ == "__main__":
    main()